 "content": "def transform(grid):
    """Fill cells between successive 5s in each row and column with 3."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # Horizontal spans, determined from the original marker positions.
    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value == 5]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                out[r][c] = 3

    # Vertical spans, also determined from original marker positions.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == 5]
        for top, bottom in zip(marks, marks[1:]):
            for r in range(top + 1, bottom):
                out[r][c] = 3

    return out
